import { BinaryResultPicker, ContextualHelpIcon, ResultPicker } from "@/components/quality/QualityUi";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Progress } from "@/components/ui/progress";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { MODULES, SENSORY_FIELDS, suggestionLocationsForFactory } from "@/lib/quality";
import { readControlFactoryScope, writeControlFactoryScope } from "@/lib/controlFactoryScope";
import { trpc } from "@/lib/trpc";
import { FragileOperationsPanel } from "@/components/quality/FragileOperationsPanel";
import { DISPATCH_CONTROL_CATALOG } from "@shared/dispatch-control";
import { AlertTriangle, ArrowLeft, Boxes, CalendarClock, CheckCircle2, CircleAlert, CircleHelp, ClipboardCheck, Factory, FilePlus2, FlaskConical, Gauge, ImagePlus, Lightbulb, MapPin, PackageSearch, Pencil, Plus, ShieldCheck, Truck } from "lucide-react";
import React, { FormEvent, useEffect, useMemo, useState } from "react";
import { Link, useRoute } from "wouter";
import { toast } from "sonner";

type Result = "C" | "NC" | "N/A";
const BPHF_CRITERIA = ["Estado de limpeza e conservação do fardamento", "Higienização das mãos dos manipuladores", "Cumprimento geral das regras de BPHF"];
const BPHF_CRITERIA_HELP: Record<(typeof BPHF_CRITERIA)[number], string> = {
  "Estado de limpeza e conservação do fardamento": "Confirme que o fardamento está limpo, íntegro e adequado à função, sem sujidade visível ou danos que possam comprometer a higiene.",
  "Higienização das mãos dos manipuladores": "Observe se a lavagem e desinfeção das mãos é realizada nos momentos necessários, com técnica adequada e sem práticas que possam recontaminar as mãos.",
  "Cumprimento geral das regras de BPHF": "Avalie o cumprimento global das boas práticas aplicáveis à área, incluindo comportamento higiénico, prevenção de contaminação e organização do posto.",
};

type FactoryOption = { id: number; name: string; code?: string };
type ControlFactoryScope = { factories: FactoryOption[]; factoryId: string; setFactoryId: (value: string) => void };
export const ControlFactoryContext = React.createContext<ControlFactoryScope>({ factories: [], factoryId: "", setFactoryId: () => undefined });
const useControlFactory = () => React.useContext(ControlFactoryContext);
type ModuleProgress = { expected: number; completed: number; registeredToday: number; pending: string[]; percentage: number };
const ModuleProgressContext = React.createContext<{ items: Record<string, ModuleProgress>; isLoading: boolean }>({ items: {}, isLoading: false });

function ModuleHeader({ label, description, icon: Icon, critical = false }: { label: string; description: string; icon: typeof ClipboardCheck; critical?: boolean }) {
  const { factories, factoryId, setFactoryId } = useControlFactory();
  const helpAnchor = ({ "Verificação de BPHF": "bphf", "Verificação de detetores de metais": "metal_detectors", "Controlo sensorial de produto acabado": "sensory", "Controlo de amostras em shelf-life": "shelf_life", "Checklist mensal": "monthly_checklist", "Caixas de sugestões": "suggestion_boxes", "Quebráveis": "fragile_items", "Controlo à expedição": "dispatch_control" } as Record<string, string>)[label] ?? "bphf";
  const selectClass = critical ? "border-red-200 bg-white text-red-900" : "border-slate-600 bg-slate-800 text-white [&>svg]:text-slate-300";
  const progressState = React.useContext(ModuleProgressContext);
  const progress = progressState.items[helpAnchor];
  const progressValue = progress?.percentage ?? 0;
  const progressDetail = progress?.expected ? `${progress.completed}/${progress.expected} verificações concluídas hoje` : `${progress?.registeredToday ?? 0} registo${progress?.registeredToday === 1 ? "" : "s"} efetuado${progress?.registeredToday === 1 ? "" : "s"} hoje`;

  return <header className={critical ? "rounded-2xl border border-red-200 bg-red-50 px-6 py-5" : "rounded-2xl bg-slate-900 px-6 py-5 text-white"}>
    <div className="flex flex-col gap-5 xl:flex-row xl:items-center xl:justify-between">
      <div className="flex min-w-0 items-center gap-3"><Link href="/controlos"><Button variant={critical ? "outline" : "secondary"} size="icon" className={critical ? "border-red-200 bg-white text-red-800 hover:bg-red-100" : "bg-slate-800 text-white hover:bg-slate-700"}><ArrowLeft className="h-4 w-4" /></Button></Link><div className="flex min-w-0 items-center gap-3"><div className={critical ? "rounded-xl bg-red-100 p-3 text-red-700" : "rounded-xl bg-teal-500/15 p-3 text-teal-300"}><Icon className="h-6 w-6" /></div><div><p className={critical ? "font-mono-ui text-xs uppercase tracking-[0.17em] text-red-700" : "font-mono-ui text-xs uppercase tracking-[0.17em] text-teal-300"}>Registo operacional</p><h1 className="mt-1 text-2xl font-semibold tracking-tight">{label}</h1><p className={critical ? "mt-1 text-sm text-red-800" : "mt-1 text-sm text-slate-300"}>{description}</p></div></div></div>
      <div className="flex flex-col gap-2 sm:flex-row sm:items-stretch"><div className={critical ? "rounded-xl border border-red-200 bg-white/80 p-3" : "rounded-xl border border-slate-700 bg-slate-800/70 p-3"}><div className="flex items-center gap-2"><Factory className={critical ? "h-4 w-4 text-red-700" : "h-4 w-4 text-teal-300"} /><span className={critical ? "text-xs font-medium text-red-800" : "text-xs font-medium text-slate-200"}>Fábrica / linha</span></div><Select value={factoryId} onValueChange={setFactoryId}><SelectTrigger className={`mt-2 w-full min-w-60 ${selectClass}`}><SelectValue placeholder="Selecione a fábrica" /></SelectTrigger><SelectContent>{factories.map((factory) => <SelectItem key={factory.id} value={String(factory.id)}>{factory.name}</SelectItem>)}</SelectContent></Select></div><Link href={`/ajuda#${helpAnchor}`}><Button variant={critical ? "outline" : "secondary"} className={critical ? "border-red-200 bg-white text-red-800 hover:bg-red-100" : "bg-slate-800 text-white hover:bg-slate-700"}><CircleHelp className="mr-2 h-4 w-4" />Ajuda</Button></Link></div>
    </div>
    {factoryId && <div className={critical ? "mt-5 rounded-xl border border-red-200 bg-white/80 p-3" : "mt-5 rounded-xl border border-slate-700 bg-slate-800/70 p-3"} aria-label="Evolução do preenchimento do dia"><div className="flex items-center justify-between gap-4"><span className={critical ? "text-sm font-medium text-red-900" : "text-sm font-medium text-white"}>Preenchimento de hoje</span><span className={critical ? "font-mono-ui text-sm text-red-800" : "font-mono-ui text-sm text-teal-300"}>{progressState.isLoading ? "A calcular…" : `${progressValue}%`}</span></div><Progress value={progressValue} className="mt-2 h-2" /><p className={critical ? "mt-2 text-xs text-red-800" : "mt-2 text-xs text-slate-300"}>{progressState.isLoading ? "A obter os registos do dia…" : progressDetail}</p>{!progressState.isLoading && progress?.pending.length ? <div className={critical ? "mt-3 border-t border-red-200 pt-3" : "mt-3 border-t border-slate-700 pt-3"}><p className={critical ? "text-xs font-semibold uppercase tracking-wide text-red-800" : "text-xs font-semibold uppercase tracking-wide text-teal-300"}>Pendentes hoje</p><ul className={critical ? "mt-1 space-y-1 text-xs text-red-900" : "mt-1 space-y-1 text-xs text-slate-200"}>{progress.pending.map((item) => <li key={item}>• {item}</li>)}</ul></div> : !progressState.isLoading && progress?.expected ? <p className={critical ? "mt-3 text-xs font-medium text-emerald-800" : "mt-3 text-xs font-medium text-emerald-300"}>Sem verificações pendentes neste controlo.</p> : null}</div>}
  </header>;
}

function Notes({ value, onChange, required = false }: { value: string; onChange: (value: string) => void; required?: boolean }) { return <div className="space-y-2"><Label>Observações {required ? "(obrigatórias)" : ""}</Label><Textarea value={value} required={required} onChange={(event) => onChange(event.target.value)} placeholder="Registe observações, evidências ou contexto relevante." /></div>; }

export default function ModuleControl() {
  const [, params] = useRoute("/controlos/:module");
  const module = params?.module ?? "bphf";
  const config = MODULES.find((item) => item.id === module);
  const metadata = trpc.quality.metadata.useQuery();
  const bphfAreas = Array.from(new Set(metadata.data?.areas.filter((area) => area.group === "bphf").map((area) => area.name) ?? []));
  const factories = metadata.data?.factories ?? [];
  const [factoryId, setFactoryId] = useState(() => new URLSearchParams(window.location.search).get("factoryId") ?? readControlFactoryScope());
  const metalAreasForFactory = factoryId ? metadata.data?.areas.filter((area) => area.group === "metal" && area.factoryId === Number(factoryId)).map((area) => area.name) ?? [] : [];
  useEffect(() => { writeControlFactoryScope(factoryId); }, [factoryId]);
  const bphfAreasForFactory = factoryId ? metadata.data?.areas.filter((area) => area.group === "bphf" && area.factoryId === Number(factoryId)).map((area) => area.name) ?? [] : [];
  const dashboard = trpc.quality.dashboard.useQuery(factoryId ? { factoryId: Number(factoryId) } : undefined, { enabled: Boolean(factoryId) });
  const utils = trpc.useUtils();
  const createEntry = trpc.quality.createEntry.useMutation({ onSuccess: (data) => { utils.quality.dashboard.invalidate(); utils.quality.reports.invalidate(); utils.quality.listNcs.invalidate(); utils.quality.fragilePending.invalidate(); toast[data.critical ? "error" : "success"](data.critical ? "Incidência crítica registada. Crie uma Não Conformidade no formulário próprio se necessário." : "Controlo registado com sucesso."); }, onError: (error) => toast.error(error.message) });
  if (!config) return <div className="p-8">Módulo não encontrado.</div>;
  const scopedCreateEntry = {
    isPending: createEntry.isPending,
    mutate: (input: any) => { if (!factoryId) return toast.error("Selecione a fábrica ou linha antes de registar o controlo."); createEntry.mutate({ ...input, factoryId: Number(factoryId) }); },
    mutateAsync: async (input: any) => { if (!factoryId) { toast.error("Selecione a fábrica ou linha antes de registar o controlo."); throw new Error("Fábrica obrigatória"); } return createEntry.mutateAsync({ ...input, factoryId: Number(factoryId) }); },
  };
  const props = { createEntry: scopedCreateEntry };
  return <ControlFactoryContext.Provider value={{ factories, factoryId, setFactoryId }}><ModuleProgressContext.Provider value={{ items: (dashboard.data?.moduleProgress as Record<string, ModuleProgress> | undefined) ?? {}, isLoading: dashboard.isLoading }}><div className="app-grid min-h-full -m-4 p-4 md:-m-6 md:p-6"><section className="mx-auto max-w-5xl space-y-6">{module === "bphf" && <Bphf {...props} areas={bphfAreasForFactory} />}{module === "metal_detectors" && <MetalDetectors {...props} areas={metalAreasForFactory} />}{module === "sensory" && <Sensory {...props} areas={bphfAreas} />}{module === "shelf_life" && <ShelfLife {...props} areas={bphfAreas} />}{module === "monthly_checklist" && <MonthlyChecklist {...props} />}{module === "suggestion_boxes" && <SuggestionBoxes {...props} factoryId={factoryId} />}{module === "fragile_items" && <><ModuleHeader label="Quebráveis" description="Inspecione os pontos por periodicidade, área e estado de integridade." icon={Boxes} /><FragileOperationsPanel {...props} factoryId={factoryId} showHeader={false} /></>}{module === "dispatch_control" && <DispatchControl />}</section></div></ModuleProgressContext.Provider></ControlFactoryContext.Provider>;
}

export function Bphf({ createEntry, areas }: any) {
  const [area, setArea] = useState("");
  const areaSignature = areas.join("|");
  const [results, setResults] = useState<Record<string, Result>>(() => Object.fromEntries(BPHF_CRITERIA.map((item) => [item, "C"])));
  const [notes, setNotes] = useState<Record<string, string>>({});
  const [completed, setCompleted] = useState(false);
  useEffect(() => setArea(""), [areaSignature]);
  async function submit(event: FormEvent) { event.preventDefault(); const ncs = BPHF_CRITERIA.filter((item) => results[item] === "NC"); if (ncs.some((item) => !notes[item]?.trim())) return toast.error("Inclua uma observação em cada item NC."); await Promise.all(BPHF_CRITERIA.map((item) => createEntry.mutateAsync({ module: "bphf", title: item, area, result: results[item], notes: notes[item] || undefined, payload: { criterion: item }, createNonconformity: false, severity: "medium" }))); setCompleted(true); toast.success(`${BPHF_CRITERIA.length} verificações BPHF registadas.`); }
  if (completed) return <><ModuleHeader label="Verificação de BPHF" description="Registe a verificação das boas práticas por área de trabalho." icon={ShieldCheck} /><Card className="border border-emerald-200 bg-emerald-50/60 shadow-sm"><CardHeader><div className="flex items-start gap-3"><div className="rounded-xl bg-emerald-100 p-3 text-emerald-700"><CheckCircle2 className="h-6 w-6" /></div><div><CardTitle className="text-emerald-950">Verificação concluída</CardTitle><CardDescription className="mt-1 text-emerald-800">Os três critérios de BPHF foram registados para a área {area}. Este registo está fechado para evitar submissões duplicadas.</CardDescription></div></div></CardHeader><CardContent className="space-y-3"><div className="divide-y overflow-hidden rounded-xl border border-emerald-100 bg-white">{BPHF_CRITERIA.map((criterion) => <div key={criterion} className="flex flex-col gap-2 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-medium text-slate-900">{criterion}</p>{notes[criterion] && <p className="mt-1 text-sm text-slate-600">{notes[criterion]}</p>}</div><Badge className={results[criterion] === "NC" ? "bg-red-600 text-white hover:bg-red-600" : "bg-emerald-100 text-emerald-800 hover:bg-emerald-100"}>{results[criterion] === "NC" ? "NC" : "C"}</Badge></div>)}</div><Button variant="outline" className="w-full border-emerald-200 text-emerald-800 hover:bg-emerald-100" onClick={() => { setCompleted(false); setArea(""); setResults(Object.fromEntries(BPHF_CRITERIA.map((item) => [item, "C"]))); setNotes({}); }}>Iniciar nova verificação BPHF</Button></CardContent></Card></>;
  return <><ModuleHeader label="Verificação de BPHF" description="Registe a verificação das boas práticas por área de trabalho." icon={ShieldCheck} /><form onSubmit={submit} className="space-y-5"><Card className="border-0 panel-shadow"><CardHeader><CardTitle>Área de verificação</CardTitle><CardDescription>{areas.length ? "Selecione a área da fábrica ou linha antes de avaliar os três critérios obrigatórios." : "Selecione primeiro a fábrica ou linha produtiva para disponibilizar as respetivas áreas BPHF."}</CardDescription></CardHeader><CardContent><Select value={area} onValueChange={setArea} disabled={!areas.length}><SelectTrigger className="max-w-md"><SelectValue placeholder={areas.length ? "Selecione a área" : "Selecione primeiro a fábrica"} /></SelectTrigger><SelectContent>{areas.map((item: string) => <SelectItem value={item} key={item}>{item}</SelectItem>)}</SelectContent></Select></CardContent></Card>{BPHF_CRITERIA.map((criterion, index) => <Card key={criterion} className="border-0 panel-shadow"><CardContent className="space-y-4 p-5"><div className="flex items-start gap-3"><span className="font-mono-ui rounded-lg bg-teal-50 px-2 py-1 text-xs font-semibold text-teal-700">0{index + 1}</span><div><div className="flex items-start gap-1.5"><p className="font-medium">{criterion}</p><ContextualHelpIcon label={`Explicação do critério BPHF: ${criterion}`} className="mt-0.5 shrink-0">{BPHF_CRITERIA_HELP[criterion]}</ContextualHelpIcon></div><p className="mt-1 text-sm text-muted-foreground">Resultado aplicável à área selecionada: {area || "por selecionar"}</p></div></div><ResultPicker value={results[criterion]} onChange={(value) => setResults((current) => ({ ...current, [criterion]: value }))} /><Notes value={notes[criterion] ?? ""} onChange={(value) => setNotes((current) => ({ ...current, [criterion]: value }))} required={results[criterion] === "NC"} /></CardContent></Card>)}<Button size="lg" className="w-full" disabled={createEntry.isPending || !area}>{createEntry.isPending ? "A registar…" : "Concluir verificação BPHF"}</Button></form></>;
}

function MetalDetectors({ createEntry, areas }: any) {
  const [area, setArea] = useState(""); const [product, setProduct] = useState(""); const [lot, setLot] = useState(""); const [result, setResult] = useState<"C" | "NC">("C"); const [notes, setNotes] = useState("");
  const areaSignature = areas.join("|");
  useEffect(() => setArea(""), [areaSignature]);
  function submit(event: FormEvent) { event.preventDefault(); if (result === "NC" && !notes.trim()) return toast.error("A observação é obrigatória para um resultado NC."); createEntry.mutate({ module: "metal_detectors", title: `Detetor de metais — ${area}${product ? ` · ${product}` : ""}`, area, result, notes, payload: { product, lot }, createNonconformity: false, severity: "critical" }); }
  return <><ModuleHeader label="Verificação de detetores de metais" description="Registe o teste por linha ou área da fábrica selecionada." icon={Gauge} critical /><form onSubmit={submit} className="space-y-5"><Card className="border-0 panel-shadow"><CardContent className="space-y-5 p-6"><div className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-900"><div className="flex gap-3"><AlertTriangle className="h-5 w-5 shrink-0 text-red-600" /><div><p className="font-semibold">Regra crítica ativa</p><p className="mt-1 text-red-800">Um resultado NC fica registado como incidência crítica. Se justificar uma Não Conformidade, crie-a no formulário próprio e associe a incidência.</p></div></div></div><div className="grid gap-4 md:grid-cols-3"><div className="space-y-2"><Label>Linha / área</Label><Select value={area} onValueChange={setArea} disabled={!areas.length}><SelectTrigger><SelectValue placeholder={areas.length ? "Selecione a linha" : "Selecione primeiro a fábrica ou linha"} /></SelectTrigger><SelectContent>{areas.map((item: string) => <SelectItem value={item} key={item}>{item}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Produto</Label><Input value={product} onChange={(event) => setProduct(event.target.value)} placeholder="Produto testado" /></div><div className="space-y-2"><Label>Lote</Label><Input value={lot} onChange={(event) => setLot(event.target.value)} placeholder="Lote" /></div></div><div className="space-y-2"><Label>Resultado do teste</Label><BinaryResultPicker value={result} onChange={setResult} /></div><Notes value={notes} onChange={setNotes} required={result === "NC"} /><Button className="w-full" size="lg" variant={result === "NC" ? "destructive" : "default"} disabled={!area}>{result === "NC" ? "Registar incidência crítica" : "Concluir verificação"}</Button></CardContent></Card></form></>;
}

function Sensory({ createEntry, areas }: any) {
  const [product, setProduct] = useState(""); const [lot, setLot] = useState(""); const [area, setArea] = useState(""); const [notes, setNotes] = useState(""); const [scores, setScores] = useState({ aspeto: 3, fimDeBoca: 3, cor: 3, cheiro: 3, textura: 3, sabor: 3 });
  const scoreInput = useMemo(() => scores, [scores]); const calculation = trpc.quality.calculateSensory.useQuery(scoreInput);
  function submit(event: FormEvent) { event.preventDefault(); createEntry.mutate({ module: "sensory", title: `Controlo sensorial${product ? ` — ${product}` : ""}`, area, result: calculation.data && calculation.data.percentage >= 50 ? "C" : "NC", notes, payload: { product, lot, scores, calculation: calculation.data, weights: { Aspeto: "10%", "Fim de boca": "15%", Cor: "15%", Cheiro: "10%", Textura: "10%", Sabor: "40%" } }, createNonconformity: Boolean(calculation.data && calculation.data.percentage < 50), severity: "medium" }); }
  return <><ModuleHeader label="Controlo sensorial de produto acabado" description="Avalie o produto acabado com os seis parâmetros e pesos fixos definidos." icon={FlaskConical} /><form onSubmit={submit} className="space-y-5"><Card className="border-0 panel-shadow"><CardContent className="grid gap-4 p-6 md:grid-cols-3"><div className="space-y-2"><Label>Produto</Label><Input required value={product} onChange={(event) => setProduct(event.target.value)} placeholder="Produto acabado" /></div><div className="space-y-2"><Label>Lote</Label><Input required value={lot} onChange={(event) => setLot(event.target.value)} placeholder="Lote" /></div><div className="space-y-2"><Label>Área</Label><Select value={area} onValueChange={setArea}><SelectTrigger><SelectValue placeholder="Selecione a área" /></SelectTrigger><SelectContent>{areas.map((item: string) => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select></div></CardContent></Card><div className="grid gap-4 md:grid-cols-2">{SENSORY_FIELDS.map((field) => <Card key={field.key} className="border-0 panel-shadow"><CardContent className="flex items-center justify-between p-5"><div><p className="font-medium">{field.label}</p><p className="font-mono-ui mt-1 text-xs text-teal-700">Peso fixo: {field.weight}</p></div><Select value={String(scores[field.key])} onValueChange={(value) => setScores((current) => ({ ...current, [field.key]: Number(value) }))}><SelectTrigger className="w-28"><SelectValue /></SelectTrigger><SelectContent>{[1, 2, 3, 4, 5].map((value) => <SelectItem value={String(value)} key={value}>{value} / 5</SelectItem>)}</SelectContent></Select></CardContent></Card>)}</div><Card className="border-0 panel-shadow"><CardContent className="grid gap-6 p-6 md:grid-cols-[1fr_auto]"><Notes value={notes} onChange={setNotes} required={Boolean(calculation.data && calculation.data.percentage < 50)} /><div className="rounded-2xl bg-slate-900 px-7 py-5 text-center text-white"><p className="font-mono-ui text-xs uppercase tracking-[0.15em] text-teal-300">Resultado ponderado</p><p className="mt-2 font-mono-ui text-4xl font-semibold">{calculation.data?.percentage ?? 0}%</p><p className="mt-1 text-sm text-slate-300">{calculation.data?.scoreOnFive ?? 0} / 5</p><Badge className={calculation.data && calculation.data.percentage >= 50 ? "mt-3 bg-emerald-500 text-emerald-950 hover:bg-emerald-500" : "mt-3 bg-red-500 text-white hover:bg-red-500"}>{calculation.data && calculation.data.percentage >= 50 ? "Conforme" : "Não conforme"}</Badge></div></CardContent></Card><Button size="lg" className="w-full" disabled={!area}>Registar controlo sensorial</Button></form></>;
}

export function DispatchControl() {
  const { factoryId } = useControlFactory();
  const utils = trpc.useUtils();
  const [profile, setProfile] = useState<"ambiente" | "congelado">("ambiente");
  const [orderNumber, setOrderNumber] = useState(""); const [customer, setCustomer] = useState(""); const [deliveryNote, setDeliveryNote] = useState(""); const [product, setProduct] = useState(""); const [lot, setLot] = useState("");
  const [orderedBoxes, setOrderedBoxes] = useState(""); const [dispatchedBoxes, setDispatchedBoxes] = useState(""); const [productLabelResult, setProductLabelResult] = useState<"C" | "NC">("C"); const [boxLabelResult, setBoxLabelResult] = useState<"C" | "NC">("C");
  const [productTemperature, setProductTemperature] = useState(""); const [vehicleTemperature, setVehicleTemperature] = useState(""); const [observations, setObservations] = useState("");
  const profileDefinition = DISPATCH_CONTROL_CATALOG.profiles.find((item) => item.id === profile) ?? DISPATCH_CONTROL_CATALOG.profiles[0];
  const limit = profileDefinition.productTemperatureLimit;
  const completeValues = [orderedBoxes, dispatchedBoxes, productTemperature, vehicleTemperature].every((value) => value !== "");
  const calculationInput = useMemo(() => ({ orderedBoxes: Number(orderedBoxes), dispatchedBoxes: Number(dispatchedBoxes), productLabelResult, boxLabelResult, productTemperature: Number(productTemperature), vehicleTemperature: Number(vehicleTemperature), productTemperatureLimit: limit, vehicleTemperatureLimit: limit }), [orderedBoxes, dispatchedBoxes, productLabelResult, boxLabelResult, productTemperature, vehicleTemperature, limit]);
  const calculation = trpc.quality.calculateDispatchConformity.useQuery(calculationInput, { enabled: completeValues });
  const register = trpc.quality.registerDispatchControl.useMutation({
    onSuccess: (data) => { utils.quality.dashboard.invalidate(); utils.quality.reports.invalidate(); utils.quality.listNcs.invalidate(); toast[data.conformity.result === "NC" ? "error" : "success"](data.conformity.result === "NC" ? "Expedição registada como incidência. Registe uma Não Conformidade no formulário próprio se necessário." : "Controlo à expedição registado como conforme."); setOrderNumber(""); setCustomer(""); setDeliveryNote(""); setProduct(""); setLot(""); setOrderedBoxes(""); setDispatchedBoxes(""); setProductTemperature(""); setVehicleTemperature(""); setProductLabelResult("C"); setBoxLabelResult("C"); setObservations(""); },
    onError: (error) => toast.error(error.message),
  });
  const result = calculation.data;
  function submit(event: FormEvent) {
    event.preventDefault();
    if (!factoryId) return toast.error("Selecione a fábrica ou linha antes de registar o controlo.");
    if (!result) return toast.error("Preencha quantidades e temperaturas para calcular a conformidade.");
    if (result.result === "NC" && !observations.trim()) return toast.error("As observações são obrigatórias quando a expedição não está conforme.");
    register.mutate({ factoryId: Number(factoryId), profile, orderNumber, customer, deliveryNote: deliveryNote || undefined, product, lot, orderedBoxes: Number(orderedBoxes), dispatchedBoxes: Number(dispatchedBoxes), productLabelResult, boxLabelResult, productTemperature: Number(productTemperature), vehicleTemperature: Number(vehicleTemperature), observations: observations || undefined });
  }
  const resultClass = result?.result === "NC" ? "border-red-200 bg-red-50 text-red-950" : "border-teal-100 bg-teal-50 text-teal-950";
  return <><ModuleHeader label="Controlo à expedição" description="Valide a encomenda, a rotulagem e a temperatura antes de expedir o produto." icon={Truck} /><form className="space-y-5" onSubmit={submit}>
    <Card className="border-0 panel-shadow"><CardContent className="space-y-5 p-6"><div className="flex flex-col gap-4 rounded-2xl border border-slate-100 bg-slate-50 p-4 md:flex-row md:items-center md:justify-between"><div><p className="font-medium text-slate-950">Perfil de validação</p><p className="mt-1 text-sm text-slate-600">Os limites e a conformidade global são calculados automaticamente.</p></div><Select value={profile} onValueChange={(value) => setProfile(value as "ambiente" | "congelado")}><SelectTrigger className="w-full md:w-80"><SelectValue /></SelectTrigger><SelectContent>{DISPATCH_CONTROL_CATALOG.profiles.map((item) => <SelectItem key={item.id} value={item.id}>{item.label}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-4 md:grid-cols-3"><div className="space-y-2"><Label>N.º Encomenda</Label><Input required value={orderNumber} onChange={(event) => setOrderNumber(event.target.value)} /></div><div className="space-y-2"><Label>Cliente</Label><Input required value={customer} onChange={(event) => setCustomer(event.target.value)} /></div><div className="space-y-2"><Label>N.º Guia <span className="text-muted-foreground">(opcional)</span></Label><Input value={deliveryNote} onChange={(event) => setDeliveryNote(event.target.value)} /></div><div className="space-y-2"><Label>Produto</Label><Input required value={product} onChange={(event) => setProduct(event.target.value)} /></div><div className="space-y-2"><Label>Lote</Label><Input required value={lot} onChange={(event) => setLot(event.target.value)} /></div><div className="rounded-xl border border-teal-100 bg-teal-50 px-4 py-3"><p className="font-mono-ui text-xs uppercase tracking-[0.12em] text-teal-700">Limite aplicável</p><p className="mt-1 font-medium text-teal-950">{profileDefinition.label}</p><p className="mt-1 text-xs text-teal-800">Produto e veículo ≤ {limit} °C</p></div></div></CardContent></Card>
    <Card className="border-0 panel-shadow"><CardHeader><CardTitle>Verificações obrigatórias</CardTitle><CardDescription>Todos os critérios devem estar conformes para validar a expedição.</CardDescription></CardHeader><CardContent className="grid gap-5 p-6 pt-0 md:grid-cols-2"><div className="space-y-3 rounded-xl border border-slate-100 p-4"><Label>Quantidade</Label><div className="grid grid-cols-2 gap-3"><div className="space-y-2"><Label className="text-xs text-muted-foreground">N.º Cx pedidas</Label><Input required min="0" type="number" value={orderedBoxes} onChange={(event) => setOrderedBoxes(event.target.value)} /></div><div className="space-y-2"><Label className="text-xs text-muted-foreground">N.º Cx expedidas</Label><Input required min="0" type="number" value={dispatchedBoxes} onChange={(event) => setDispatchedBoxes(event.target.value)} /></div></div></div><div className="space-y-3 rounded-xl border border-slate-100 p-4"><Label>Rotulagem</Label><div className="grid grid-cols-2 gap-3"><div className="space-y-2"><Label className="text-xs text-muted-foreground">Produto</Label><BinaryResultPicker value={productLabelResult} onChange={setProductLabelResult} /></div><div className="space-y-2"><Label className="text-xs text-muted-foreground">Caixa</Label><BinaryResultPicker value={boxLabelResult} onChange={setBoxLabelResult} /></div></div></div><div className="space-y-2 rounded-xl border border-slate-100 p-4"><div className="flex items-center gap-1.5"><Label>Temp. Produto (°C)</Label><ContextualHelpIcon label="Ajuda sobre a temperatura do produto">Registe a temperatura medida no produto. Para ser conforme, deve ser igual ou inferior a {limit} °C no perfil selecionado.</ContextualHelpIcon></div><Input required type="number" step="0.1" value={productTemperature} onChange={(event) => setProductTemperature(event.target.value)} placeholder={`Máximo ${limit} °C`} /></div><div className="space-y-2 rounded-xl border border-slate-100 p-4"><div className="flex items-center gap-1.5"><Label>Temp. Veículo (°C)</Label><ContextualHelpIcon label="Ajuda sobre a temperatura do veículo">Registe a temperatura do compartimento de transporte. Para ser conforme, deve ser igual ou inferior a {limit} °C no perfil selecionado.</ContextualHelpIcon></div><Input required type="number" step="0.1" value={vehicleTemperature} onChange={(event) => setVehicleTemperature(event.target.value)} placeholder={`Máximo ${limit} °C`} /></div></CardContent></Card>
    <Card className="border-0 panel-shadow"><CardContent className="space-y-5 p-6"><div className={`rounded-2xl border p-5 ${resultClass}`}><div className="flex items-center justify-between gap-4"><div><p className="font-mono-ui text-xs uppercase tracking-[0.15em]">Conformidade global</p><p className="mt-2 text-2xl font-semibold">{result ? (result.result === "C" ? "Conforme" : "Não conforme") : "A aguardar dados"}</p><p className="mt-1 text-sm opacity-80">Quantidade, rotulagem e temperaturas são avaliadas automaticamente.</p></div>{result && <Badge className={result.result === "C" ? "bg-emerald-500 text-emerald-950 hover:bg-emerald-500" : "bg-red-500 text-white hover:bg-red-500"}>{result.result}</Badge>}</div>{result && <div className="mt-4 grid gap-2 text-sm sm:grid-cols-3"><span>Quantidade: <strong>{result.quantityResult}</strong></span><span>Temp. produto: <strong>{result.productTemperatureResult}</strong></span><span>Temp. veículo: <strong>{result.vehicleTemperatureResult}</strong></span></div>}</div><Notes value={observations} onChange={setObservations} required={result?.result === "NC"} /><Button className="w-full" size="lg" variant={result?.result === "NC" ? "destructive" : "default"} disabled={register.isPending || !factoryId || !result}>{register.isPending ? "A registar…" : result?.result === "NC" ? "Registar incidência à expedição" : "Registar controlo à expedição"}</Button></CardContent></Card>
  </form></>;
}

export function ShelfLife({ createEntry }: any) {
  const [result, setResult] = useState<"C" | "NC">("C");
  const [product, setProduct] = useState("");
  const [lot, setLot] = useState("");
  const [validity, setValidity] = useState("");
  const [reason, setReason] = useState("");
  const isNcComplete = Boolean(product.trim() && lot.trim() && validity && reason.trim());

  function submit(event: FormEvent) {
    event.preventDefault();
    if (result === "NC" && !isNcComplete) return toast.error("Em caso de NC, identifique o produto, lote, validade e motivo da incidência.");
    createEntry.mutate({
      module: "shelf_life",
      title: result === "NC" ? `Incidência shelf-life — ${product}` : "Shelf-life — Conforme",
      area: "Shelf-life",
      result,
      notes: result === "NC" ? reason : undefined,
      payload: {
        observationResult: result,
        product: result === "NC" ? product : null,
        lot: result === "NC" ? lot : null,
        validity: result === "NC" ? validity : null,
        reason: result === "NC" ? reason : null,
        dailyIncidenceGenerated: result === "NC",
      },
      createNonconformity: false,
      severity: "medium",
    });
  }

  return <><ModuleHeader label="Controlo de amostras em shelf-life" description="Registe a verificação diária como C ou NC. Os dados de rastreabilidade surgem apenas quando existe uma incidência." icon={PackageSearch} /><form onSubmit={submit} className="space-y-5"><Card className="border-0 panel-shadow"><CardContent className="space-y-5 p-6"><div className="rounded-xl border border-teal-100 bg-teal-50/70 p-4"><p className="font-medium text-teal-950">Verificação diária da amostra</p><p className="mt-1 text-sm text-teal-800">Registe primeiro o resultado. Um NC cria uma incidência diária que pode, se necessário, ser associada posteriormente a uma Não Conformidade.</p></div><div className="space-y-2"><div className="flex items-center gap-1.5"><Label>Resultado da verificação global:</Label><ContextualHelpIcon label="Explicação do resultado da verificação global">Selecione C quando a amostra estiver conforme. Escolha NC quando existir um desvio; serão pedidos os dados de rastreabilidade e criada uma incidência diária.</ContextualHelpIcon></div><BinaryResultPicker value={result} onChange={setResult} showHelp={false} /></div>{result === "NC" && <div className="space-y-5 rounded-2xl border border-red-200 bg-red-50/60 p-5"><div><p className="font-semibold text-red-950">Detalhe da incidência</p><p className="mt-1 text-sm text-red-800">Estes dados são obrigatórios para garantir a rastreabilidade da incidência.</p></div><div className="grid gap-4 md:grid-cols-3"><div className="space-y-2"><Label htmlFor="shelf-life-product">Produto</Label><Input id="shelf-life-product" required value={product} onChange={(event) => setProduct(event.target.value)} placeholder="Produto da amostra" /></div><div className="space-y-2"><Label htmlFor="shelf-life-lot">Lote</Label><Input id="shelf-life-lot" required value={lot} onChange={(event) => setLot(event.target.value)} placeholder="Lote" /></div><div className="space-y-2"><Label htmlFor="shelf-life-validity">Validade</Label><Input id="shelf-life-validity" required type="date" value={validity} onChange={(event) => setValidity(event.target.value)} /></div></div><div className="space-y-2"><Label htmlFor="shelf-life-reason">Motivo / observações da incidência</Label><Textarea id="shelf-life-reason" required value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Descreva o desvio observado na amostra." /></div></div>}<Button size="lg" className="w-full" variant={result === "NC" ? "destructive" : "default"} disabled={createEntry.isPending || (result === "NC" && !isNcComplete)}>{result === "NC" ? "Registar incidência" : "Registar verificação conforme"}</Button></CardContent></Card></form></>;
}

function MonthlyChecklist({ createEntry }: any) {
  const items = trpc.quality.listChecklistItems.useQuery(); const initialize = trpc.quality.initializeChecklist.useMutation({ onSuccess: () => { items.refetch(); toast.success("Itens iniciais de checklist configurados."); }, onError: (error) => toast.error(error.message) }); const [area, setArea] = useState("Geral"); const [results, setResults] = useState<Record<number, Result>>({}); const [notes, setNotes] = useState<Record<number, string>>({});
  const grouped = items.data?.filter((item) => item.area === area) ?? [];
  const conformity = grouped.length ? Math.round((grouped.filter((item) => (results[item.id] ?? "C") === "C").length / grouped.length) * 100) : 0;
  async function submit(event: FormEvent) { event.preventDefault(); if (grouped.some((item) => (results[item.id] ?? "C") === "NC" && !notes[item.id]?.trim())) return toast.error("Inclua observações em todos os itens NC."); await Promise.all(grouped.map((item) => { const result = results[item.id] ?? "C"; return createEntry.mutateAsync({ module: "monthly_checklist", title: item.label, area, result, notes: notes[item.id] || undefined, payload: { checklistItemId: item.id }, createNonconformity: result === "NC", severity: "medium" }); })); toast.success("Checklist mensal registada."); }
  return <><ModuleHeader label="Checklist mensal" description="Avalie os itens configuráveis por zona e acompanhe a taxa de conformidade." icon={ClipboardCheck} /><div className="flex flex-col justify-between gap-4 rounded-2xl border border-blue-100 bg-blue-50 px-5 py-4 md:flex-row md:items-center"><div><p className="font-medium text-blue-950">Itens configuráveis por administrador</p><p className="mt-1 text-sm text-blue-800">A lista é gerida na área de Configuração e fica disponível para toda a equipa.</p></div>{!items.isLoading && !items.data?.length && <Button onClick={() => initialize.mutate()} disabled={initialize.isPending}>{initialize.isPending ? "A configurar…" : "Carregar itens iniciais"}</Button>}</div><form onSubmit={submit} className="space-y-5"><Card className="border-0 panel-shadow"><CardContent className="flex flex-col gap-4 p-5 md:flex-row md:items-center md:justify-between"><div className="w-full max-w-md space-y-2"><Label>Zona</Label><Select value={area} onValueChange={setArea}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{Array.from(new Set(items.data?.map((item) => item.area) ?? ["Geral"])).map((item) => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select></div><div className="w-full max-w-xs"><div className="mb-2 flex justify-between text-sm"><span>Taxa provisória</span><span className="font-mono-ui font-semibold">{conformity}%</span></div><Progress value={conformity} /></div></CardContent></Card>{grouped.map((item, index) => { const result = results[item.id] ?? "C"; return <Card key={item.id} className="border-0 panel-shadow"><CardContent className="space-y-4 p-5"><div className="flex gap-3"><span className="font-mono-ui rounded-lg bg-blue-50 px-2 py-1 text-xs font-semibold text-blue-700">{String(index + 1).padStart(2, "0")}</span><p className="font-medium">{item.label}</p></div><ResultPicker value={result} onChange={(value) => setResults((current) => ({ ...current, [item.id]: value }))} /><Notes value={notes[item.id] ?? ""} onChange={(value) => setNotes((current) => ({ ...current, [item.id]: value }))} required={result === "NC"} /></CardContent></Card>; })}{grouped.length > 0 && <Button className="w-full" size="lg" disabled={createEntry.isPending}>Concluir checklist mensal</Button>}</form></>;
}

function SuggestionBoxes({ createEntry, factoryId }: { createEntry: any; factoryId: string }) {
  const { factories } = useControlFactory();
  const factory = factories.find((item: any) => String(item.id) === factoryId);
  const locations = suggestionLocationsForFactory(factory?.code);
  const [location, setLocation] = useState("");
  const [count, setCount] = useState("0");
  const [triage, setTriage] = useState("Por triagem");
  const [notes, setNotes] = useState("");

  useEffect(() => { setLocation(locations[0] ?? ""); }, [factory?.code]);
  function submit(event: FormEvent) { event.preventDefault(); if (!location) return; createEntry.mutate({ module: "suggestion_boxes", title: `Caixa de sugestões — ${location}`, area: location, notes, payload: { count: Number(count), triage }, createNonconformity: false, severity: "low" }); }
  return <><ModuleHeader label="Caixas de sugestões" description="Selecione a fábrica ou linha para ver apenas as caixas que lhe estão associadas." icon={Lightbulb} /><form onSubmit={submit}><Card className="border-0 panel-shadow"><CardContent className="space-y-5 p-6">{!factoryId || !locations.length ? <div className="rounded-xl border border-dashed bg-slate-50 p-4 text-sm text-muted-foreground">Selecione Fábrica 1, Fábrica 2 ou Fábrica 3/SG no topo para registar a verificação de uma caixa de sugestões.</div> : <><div className="grid gap-4 md:grid-cols-3"><div className="space-y-2"><Label>Localização</Label><Select value={location} onValueChange={setLocation}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{locations.map((item) => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>N.º de registos</Label><Input type="number" min="0" value={count} onChange={(event) => setCount(event.target.value)} /></div><div className="space-y-2"><Label>Estado de triagem</Label><Select value={triage} onValueChange={setTriage}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Por triagem", "Em análise", "Triada", "Fechada"].map((item) => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select></div></div><Notes value={notes} onChange={setNotes} /><Button className="w-full" size="lg">Registar verificação</Button></>}</CardContent></Card></form></>;
}

function FragileInspection({ createEntry }: any) {
  const items = trpc.quality.listFragileItems.useQuery(); const utils = trpc.useUtils(); const addItem = trpc.quality.addFragileItem.useMutation({ onSuccess: () => { utils.quality.listFragileItems.invalidate(); toast.success("Item adicionado ao inventário."); }, onError: (error) => toast.error(error.message) }); const [itemId, setItemId] = useState(""); const [state, setState] = useState("Íntegro"); const [notes, setNotes] = useState(""); const [dialogOpen, setDialogOpen] = useState(false); const [name, setName] = useState(""); const [location, setLocation] = useState(""); const [type, setType] = useState<"Vidro" | "Plástico rígido" | "Outro">("Vidro"); const item = items.data?.find((entry) => String(entry.id) === itemId);
  function submitInspection(event: FormEvent) { event.preventDefault(); if (!item) return toast.error("Selecione um item do inventário."); if (state !== "Íntegro" && !notes.trim()) return toast.error("A ação de contenção é obrigatória em caso de dano ou ausência."); createEntry.mutate({ module: "fragile_items", title: `Quebrável — ${item.name}`, area: item.location, result: state === "Íntegro" ? "C" : "NC", notes, payload: { fragileItemId: item.id, state, containmentAction: notes }, createNonconformity: state !== "Íntegro", severity: state === "Danificado" ? "high" : "medium" }); }
  function add(event: FormEvent) { event.preventDefault(); addItem.mutate({ name, location, itemType: type }); setDialogOpen(false); setName(""); setLocation(""); }
  return <><ModuleHeader label="Quebráveis" description="Inspecione os itens do inventário e associe a ação de contenção quando existir desvio." icon={Boxes} /><div className="flex justify-end"><Dialog open={dialogOpen} onOpenChange={setDialogOpen}><DialogTrigger asChild><Button variant="outline"><Plus className="mr-2 h-4 w-4" />Adicionar ao inventário</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Novo item quebrável</DialogTitle></DialogHeader><form onSubmit={add} className="space-y-4"><div className="space-y-2"><Label>Item</Label><Input required value={name} onChange={(event) => setName(event.target.value)} placeholder="Ex.: Luminária de proteção" /></div><div className="space-y-2"><Label>Localização</Label><Input required value={location} onChange={(event) => setLocation(event.target.value)} placeholder="Ex.: Produção T" /></div><div className="space-y-2"><Label>Tipo</Label><Select value={type} onValueChange={(value) => setType(value as any)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Vidro", "Plástico rígido", "Outro"].map((item) => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select></div><Button className="w-full">Adicionar item</Button></form></DialogContent></Dialog></div><form onSubmit={submitInspection}><Card className="border-0 panel-shadow"><CardContent className="space-y-5 p-6"><div className="grid gap-4 md:grid-cols-2"><div className="space-y-2"><Label>Item do inventário</Label><Select value={itemId} onValueChange={setItemId}><SelectTrigger><SelectValue placeholder="Selecione o item" /></SelectTrigger><SelectContent>{items.data?.map((entry) => <SelectItem key={entry.id} value={String(entry.id)}>{entry.name} — {entry.location}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Estado da inspeção</Label><Select value={state} onValueChange={setState}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Íntegro", "Danificado", "Em falta"].map((entry) => <SelectItem key={entry} value={entry}>{entry}</SelectItem>)}</SelectContent></Select></div></div><div className="space-y-2"><Label>Ação de contenção / observações</Label><Textarea value={notes} onChange={(event) => setNotes(event.target.value)} required={state !== "Íntegro"} placeholder="Obrigatório em caso de item danificado ou em falta." /></div><Button className="w-full" size="lg" variant={state === "Íntegro" ? "default" : "destructive"}>Registar inspeção</Button></CardContent></Card></form></>;
}

function FragileInspectionLegacy({ createEntry, factoryId }: { createEntry: any; factoryId: string }) {
  const [periodicity, setPeriodicity] = useState("all");
  const [area, setArea] = useState("all");
  const [itemId, setItemId] = useState("");
  const [state, setState] = useState("Íntegro");
  const [notes, setNotes] = useState("");
  const [dialogOpen, setDialogOpen] = useState(false);
  const [name, setName] = useState("");
  const [newLocation, setNewLocation] = useState("");
  const [newPeriodicity, setNewPeriodicity] = useState<"D" | "S" | "Q" | "M">("M");
  const [type, setType] = useState<"Vidro" | "Plástico rígido" | "Outro">("Outro");
  const utils = trpc.useUtils();
  const listInput = useMemo(() => ({ factoryId: factoryId ? Number(factoryId) : undefined, periodicity: periodicity === "all" ? undefined : periodicity as "D" | "S" | "Q" | "M" }), [factoryId, periodicity]);
  const items = trpc.quality.listFragileItems.useQuery(listInput);
  const addItem = trpc.quality.addFragileItem.useMutation({ onSuccess: () => { utils.quality.listFragileItems.invalidate(); toast.success("Ponto de quebrável adicionado ao inventário."); }, onError: (error) => toast.error(error.message) });
  const availableAreas = Array.from(new Set((items.data ?? []).map((entry) => entry.location))).sort();
  const visibleItems = (items.data ?? []).filter((entry) => area === "all" || entry.location === area);
  const inventoryCount = factoryId ? visibleItems.length : 0;
  const item = visibleItems.find((entry) => String(entry.id) === itemId) ?? (items.data ?? []).find((entry) => String(entry.id) === itemId);
  const periodLabel = { D: "Diário", S: "Semanal", Q: "Quinzenal", M: "Mensal" } as const;
  function submitInspection(event: FormEvent) {
    event.preventDefault();
    if (!factoryId) return toast.error("Selecione a fábrica antes de registar a inspeção.");
    if (!item) return toast.error("Selecione um ponto de controlo.");
    if (state !== "Íntegro" && !notes.trim()) return toast.error("A ação de contenção é obrigatória em caso de dano ou ausência.");
    createEntry.mutate({ module: "fragile_items", title: `Quebrável — ${item.name}`, area: item.location, result: state === "Íntegro" ? "C" : "NC", notes, payload: { fragileItemId: item.id, state, containmentAction: notes, periodicity: item.periodicity, itemType: item.itemType, sourceSheet: item.sourceSheet }, createNonconformity: state !== "Íntegro", severity: state === "Danificado" ? "high" : "medium" });
  }
  function add(event: FormEvent) {
    event.preventDefault();
    if (!factoryId) return toast.error("Selecione a fábrica antes de criar um ponto.");
    addItem.mutate({ name, location: newLocation, factoryId: Number(factoryId), periodicity: newPeriodicity, itemType: type });
    setDialogOpen(false); setName(""); setNewLocation("");
  }
  return <><ModuleHeader label="Quebráveis" description="Selecione a fábrica, a periodicidade e a área para inspecionar os pontos importados dos registos operacionais." icon={Boxes} /><div className="flex flex-col gap-4 rounded-2xl border border-teal-100 bg-teal-50/70 p-5 md:flex-row md:items-end"><div className="flex-1"><p className="font-medium text-teal-950">Pontos de controlo importados</p><p className="mt-1 text-sm text-teal-800">O inventário reflete as áreas e frequências D, S, Q e M dos ficheiros de controlo de quebráveis.</p></div><Badge className="w-fit bg-teal-700 text-white hover:bg-teal-700">{factoryId ? `${inventoryCount} pontos disponíveis` : "Selecione a fábrica"}</Badge><Dialog open={dialogOpen} onOpenChange={setDialogOpen}><DialogTrigger asChild><Button variant="outline"><Plus className="mr-2 h-4 w-4" />Adicionar ponto</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Novo ponto quebrável</DialogTitle></DialogHeader><form onSubmit={add} className="space-y-4"><div className="space-y-2"><Label>Ponto de controlo</Label><Input required value={name} onChange={(event) => setName(event.target.value)} /></div><div className="space-y-2"><Label>Área</Label><Input required value={newLocation} onChange={(event) => setNewLocation(event.target.value)} /></div><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2"><Label>Periodicidade</Label><Select value={newPeriodicity} onValueChange={(value) => setNewPeriodicity(value as "D" | "S" | "Q" | "M")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{Object.entries(periodLabel).map(([code, label]) => <SelectItem key={code} value={code}>{code} — {label}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Tipo</Label><Select value={type} onValueChange={(value) => setType(value as typeof type)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Vidro", "Plástico rígido", "Outro"].map((itemType) => <SelectItem key={itemType} value={itemType}>{itemType}</SelectItem>)}</SelectContent></Select></div></div><Button className="w-full">Adicionar ponto</Button></form></DialogContent></Dialog></div><form onSubmit={submitInspection} className="space-y-5"><Card className="border-0 panel-shadow"><CardContent className="space-y-5 p-6"><div className="grid gap-4 md:grid-cols-3"><div className="space-y-2"><Label>Periodicidade</Label><Select value={periodicity} onValueChange={(value) => { setPeriodicity(value); setArea("all"); setItemId(""); }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todas as periodicidades</SelectItem>{Object.entries(periodLabel).map(([code, label]) => <SelectItem key={code} value={code}>{code} — {label}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Área</Label><Select value={area} onValueChange={(value) => { setArea(value); setItemId(""); }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todas as áreas</SelectItem>{availableAreas.map((entry) => <SelectItem key={entry} value={entry}>{entry}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Ponto de controlo</Label><Select value={itemId} onValueChange={setItemId}><SelectTrigger><SelectValue placeholder={factoryId ? "Selecione o ponto" : "Selecione a fábrica primeiro"} /></SelectTrigger><SelectContent>{visibleItems.map((entry) => <SelectItem key={entry.id} value={String(entry.id)}>{entry.name} · {entry.periodicity}</SelectItem>)}</SelectContent></Select></div></div>{item && <div className="flex flex-wrap items-center gap-2 rounded-xl border border-slate-100 bg-slate-50 p-4"><Badge variant="outline">{item.itemType}</Badge><Badge className="bg-slate-900 text-white hover:bg-slate-900">{item.periodicity} — {periodLabel[item.periodicity]}</Badge><span className="text-sm text-muted-foreground">{item.location}</span></div>}<div className="space-y-2"><Label>Estado da inspeção</Label><Select value={state} onValueChange={setState}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Íntegro", "Danificado", "Em falta"].map((entry) => <SelectItem key={entry} value={entry}>{entry}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Ação de contenção / observações</Label><Textarea value={notes} onChange={(event) => setNotes(event.target.value)} required={state !== "Íntegro"} placeholder="Obrigatório em caso de item danificado ou em falta." /></div><Button className="w-full" size="lg" variant={state === "Íntegro" ? "default" : "destructive"} disabled={!factoryId || !item}>Registar inspeção</Button></CardContent></Card></form></>;
}

function fileAsDataUrl(file: File) {
  return new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result));
    reader.onerror = () => reject(new Error("Não foi possível ler a imagem."));
    reader.readAsDataURL(file);
  });
}

export function FragileInspectionV2({ createEntry, factoryId, preselectedItemId = null, showHeader = true }: { createEntry: any; factoryId: string; preselectedItemId?: number | null; showHeader?: boolean }) {
  const metadata = trpc.quality.metadata.useQuery();
  const utils = trpc.useUtils();
  const [periodicity, setPeriodicity] = useState("all");
  const [area, setArea] = useState("all");
  const [itemId, setItemId] = useState(preselectedItemId ? String(preselectedItemId) : "");
  const [state, setState] = useState("Íntegro");
  const [notes, setNotes] = useState("");
  const [createOpen, setCreateOpen] = useState(false);
  const [editOpen, setEditOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [name, setName] = useState("");
  const [location, setLocation] = useState("");
  const [selectedFactoryId, setSelectedFactoryId] = useState("");
  const [selectedPeriodicity, setSelectedPeriodicity] = useState<"D" | "S" | "Q" | "M">("M");
  const [selectedType, setSelectedType] = useState<"Vidro" | "Plástico rígido" | "Outro">("Outro");
  const factoryInput = useMemo(() => factoryId ? { factoryId: Number(factoryId) } : undefined, [factoryId]);
  const items = trpc.quality.listFragileItems.useQuery(factoryInput, { enabled: Boolean(factoryId) });
  const addItem = trpc.quality.addFragileItem.useMutation({ onSuccess: () => { utils.quality.listFragileItems.invalidate(); toast.success("Ponto de controlo criado."); setCreateOpen(false); }, onError: (error) => toast.error(error.message) });
  const updateItem = trpc.quality.updateFragileItem.useMutation({ onSuccess: () => { utils.quality.listFragileItems.invalidate(); toast.success("Ponto de controlo atualizado."); }, onError: (error) => toast.error(error.message) });
  const uploadImage = trpc.quality.uploadFragileReferenceImage.useMutation({ onSuccess: () => { utils.quality.listFragileItems.invalidate(); toast.success("Imagem de referência carregada."); }, onError: (error) => toast.error(error.message) });
  const periodLabel = { D: "Diário", S: "Semanal", Q: "Quinzenal", M: "Mensal" } as const;
  const factoryItems = items.data ?? [];
  const availableAreas = Array.from(new Set(factoryItems.map((entry) => entry.location))).sort();
  const visibleItems = factoryItems.filter((entry) => (periodicity === "all" || entry.periodicity === periodicity) && (area === "all" || entry.location === area));
  const selectedItem = visibleItems.find((entry) => String(entry.id) === itemId) ?? factoryItems.find((entry) => String(entry.id) === itemId);
  const factories = metadata.data?.factories ?? [];

  function resetEditor(entry?: any) {
    setEditing(entry ?? null);
    setName(entry?.name ?? "");
    setLocation(entry?.location ?? "");
    setSelectedFactoryId(String(entry?.factoryId ?? factoryId ?? ""));
    setSelectedPeriodicity(entry?.periodicity ?? "M");
    setSelectedType(entry?.itemType ?? "Outro");
  }

  function openCreate() { resetEditor(); setSelectedFactoryId(factoryId); setCreateOpen(true); }
  function openEdit(entry: any) { resetEditor(entry); setEditOpen(true); }

  function saveNew(event: FormEvent) {
    event.preventDefault();
    if (!selectedFactoryId) return toast.error("Selecione a fábrica do novo ponto.");
    addItem.mutate({ name, location, factoryId: Number(selectedFactoryId), periodicity: selectedPeriodicity, itemType: selectedType });
  }

  function saveEdit(event: FormEvent) {
    event.preventDefault();
    if (!editing) return;
    if (!selectedFactoryId) return toast.error("Selecione a fábrica do ponto de controlo.");
    updateItem.mutate({ id: editing.id, name, location, factoryId: Number(selectedFactoryId), periodicity: selectedPeriodicity, itemType: selectedType }, { onSuccess: () => setEditOpen(false) });
  }

  async function addReferenceImage(file?: File) {
    if (!file || !editing) return;
    if (!file.type.match(/^image\/(jpeg|png|webp)$/)) return toast.error("Use uma imagem JPG, PNG ou WEBP.");
    if (file.size > 4_500_000) return toast.error("A imagem deve ter no máximo 4,5 MB.");
    try {
      const dataUrl = await fileAsDataUrl(file);
      uploadImage.mutate({ itemId: editing.id, fileName: file.name, mimeType: file.type as "image/jpeg" | "image/png" | "image/webp", dataUrl }, { onSuccess: (result) => setEditing((current: any) => current ? { ...current, referenceImageUrl: result.url, referenceImageName: file.name } : current) });
    } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível carregar a imagem."); }
  }

  function submitInspection(event: FormEvent) {
    event.preventDefault();
    if (!factoryId) return toast.error("Selecione a fábrica antes de registar a inspeção.");
    if (!selectedItem) return toast.error("Selecione um ponto de controlo.");
    if (state !== "Íntegro" && !notes.trim()) return toast.error("A ação de contenção é obrigatória em caso de dano ou ausência.");
    createEntry.mutate({ module: "fragile_items", title: `Quebrável — ${selectedItem.name}`, area: selectedItem.location, result: state === "Íntegro" ? "C" : "NC", notes, payload: { fragileItemId: selectedItem.id, state, containmentAction: notes, periodicity: selectedItem.periodicity, referenceImageUrl: selectedItem.referenceImageUrl }, createNonconformity: state !== "Íntegro", severity: state === "Danificado" ? "high" : "medium" });
  }

  const pointForm = (onSubmit: (event: FormEvent) => void, submitLabel: string, includeImage = false) => <form onSubmit={onSubmit} className="space-y-4"><div className="space-y-2"><Label>Nome do ponto de controlo</Label><Input required value={name} onChange={(event) => setName(event.target.value)} placeholder="Ex.: Proteção acrílica da fatiadora" /></div><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2"><Label>Fábrica / linha</Label><Select value={selectedFactoryId} onValueChange={setSelectedFactoryId}><SelectTrigger><SelectValue placeholder="Selecione a fábrica" /></SelectTrigger><SelectContent>{factories.map((factory) => <SelectItem key={factory.id} value={String(factory.id)}>{factory.name}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Área</Label><Input required value={location} onChange={(event) => setLocation(event.target.value)} placeholder="Ex.: Produção T" /></div></div><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2"><Label>Periodicidade</Label><Select value={selectedPeriodicity} onValueChange={(value) => setSelectedPeriodicity(value as "D" | "S" | "Q" | "M")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{Object.entries(periodLabel).map(([code, label]) => <SelectItem key={code} value={code}>{code} — {label}</SelectItem>)}</SelectContent></Select></div><div className="space-y-2"><Label>Tipo</Label><Select value={selectedType} onValueChange={(value) => setSelectedType(value as "Vidro" | "Plástico rígido" | "Outro")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Vidro", "Plástico rígido", "Outro"].map((type) => <SelectItem key={type} value={type}>{type}</SelectItem>)}</SelectContent></Select></div></div>{includeImage && <div className="space-y-3 rounded-xl border border-dashed border-teal-200 bg-teal-50/60 p-4"><div className="flex items-center gap-2 text-sm font-medium text-teal-900"><ImagePlus className="h-4 w-4" />Imagem de referência</div>{editing?.referenceImageUrl && <img src={editing.referenceImageUrl} alt={`Referência: ${editing.name}`} className="h-32 w-full rounded-lg border border-teal-100 object-cover" />}<Input type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => addReferenceImage(event.target.files?.[0])} disabled={uploadImage.isPending} /><p className="text-xs text-teal-800">JPG, PNG ou WEBP, até 4,5 MB. A imagem fica associada a este ponto de controlo.</p></div>}<Button className="w-full" disabled={addItem.isPending || updateItem.isPending}>{addItem.isPending || updateItem.isPending ? "A guardar…" : submitLabel}</Button></form>;

  return <>{showHeader && <ModuleHeader label="Quebráveis" description="Gira os pontos por fábrica e área, incluindo a periodicidade e a imagem de referência de cada inspeção." icon={Boxes} />}<div className="flex flex-col gap-4 rounded-2xl border border-teal-100 bg-teal-50/70 p-5 md:flex-row md:items-end"><div className="flex-1"><p className="font-medium text-teal-950">Catálogo operacional de pontos</p><p className="mt-1 text-sm text-teal-800">Selecione uma fábrica para consultar, criar ou editar os pontos de controlo associados.</p></div><Badge className="w-fit bg-teal-700 text-white hover:bg-teal-700">{factoryId ? `${factoryItems.length} pontos na fábrica` : "Selecione a fábrica"}</Badge><Button variant="outline" onClick={openCreate}><Plus className="mr-2 h-4 w-4" />Adicionar ponto</Button></div><div className="grid gap-5 lg:grid-cols-[1.15fr_.85fr]"><Card className="border-0 panel-shadow"><CardHeader><CardTitle className="flex items-center gap-2"><MapPin className="h-5 w-5 text-teal-700" />Gerir pontos de controlo</CardTitle><CardDescription>Filtre os pontos da fábrica selecionada e edite o respetivo contexto operacional.</CardDescription></CardHeader><CardContent className="space-y-4"><div className="grid gap-3 sm:grid-cols-2"><Select value={periodicity} onValueChange={(value) => { setPeriodicity(value); setArea("all"); setItemId(""); }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todas as periodicidades</SelectItem>{Object.entries(periodLabel).map(([code, label]) => <SelectItem key={code} value={code}>{code} — {label}</SelectItem>)}</SelectContent></Select><Select value={area} onValueChange={(value) => { setArea(value); setItemId(""); }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todas as áreas</SelectItem>{availableAreas.map((entry) => <SelectItem key={entry} value={entry}>{entry}</SelectItem>)}</SelectContent></Select></div>{!factoryId ? <p className="rounded-xl bg-slate-50 p-4 text-sm text-muted-foreground">Selecione a fábrica no topo para listar os pontos de controlo.</p> : <div className="max-h-[420px] space-y-2 overflow-y-auto pr-1">{visibleItems.slice(0, 40).map((entry) => <div key={entry.id} className="flex items-center gap-3 rounded-xl border border-slate-100 bg-white p-3"><div className="h-11 w-11 shrink-0 overflow-hidden rounded-lg bg-teal-50 text-teal-700">{entry.referenceImageUrl ? <img src={entry.referenceImageUrl} alt="" className="h-full w-full object-cover" /> : <ImagePlus className="m-3 h-5 w-5" />}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{entry.name}</p><p className="mt-0.5 truncate text-xs text-muted-foreground">{entry.location} · {entry.periodicity} — {periodLabel[entry.periodicity]}</p></div><Button type="button" size="icon" variant="outline" aria-label={`Editar ${entry.name}`} onClick={() => openEdit(entry)}><Pencil className="h-4 w-4" /></Button></div>)}{visibleItems.length > 40 && <p className="px-2 py-1 text-xs text-muted-foreground">Mostram-se os primeiros 40 pontos. Use os filtros para restringir a lista.</p>}{!visibleItems.length && <p className="rounded-xl bg-slate-50 p-4 text-sm text-muted-foreground">Não existem pontos com estes filtros.</p>}</div>}</CardContent></Card><form onSubmit={submitInspection}><Card className="border-0 panel-shadow"><CardHeader><CardTitle>Registar inspeção</CardTitle><CardDescription>O ponto selecionado transporta a fábrica, área e periodicidade para o registo.</CardDescription></CardHeader><CardContent className="space-y-5"><div className="space-y-2"><Label>Ponto de controlo</Label><Select value={itemId} onValueChange={setItemId}><SelectTrigger><SelectValue placeholder={factoryId ? "Selecione o ponto" : "Selecione a fábrica primeiro"} /></SelectTrigger><SelectContent>{visibleItems.map((entry) => <SelectItem key={entry.id} value={String(entry.id)}>{entry.name} · {entry.periodicity}</SelectItem>)}</SelectContent></Select></div>{selectedItem && <div className="space-y-3 rounded-xl border border-teal-100 bg-teal-50/50 p-4">{selectedItem.referenceImageUrl && <img src={selectedItem.referenceImageUrl} alt={`Referência de ${selectedItem.name}`} className="h-32 w-full rounded-lg object-cover" />}<div className="flex flex-wrap gap-2"><Badge variant="outline">{selectedItem.itemType}</Badge><Badge className="bg-slate-900 text-white hover:bg-slate-900">{selectedItem.periodicity} — {periodLabel[selectedItem.periodicity]}</Badge><span className="text-sm text-muted-foreground">{selectedItem.location}</span></div></div>}<div className="space-y-2"><Label>Estado da inspeção</Label><Select value={state} onValueChange={setState}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Íntegro", "Danificado", "Em falta"].map((entry) => <SelectItem key={entry} value={entry}>{entry}</SelectItem>)}</SelectContent></Select></div><Notes value={notes} onChange={setNotes} required={state !== "Íntegro"} /><Button className="w-full" size="lg" variant={state === "Íntegro" ? "default" : "destructive"} disabled={!factoryId || !selectedItem}>Registar inspeção</Button></CardContent></Card></form></div><Dialog open={createOpen} onOpenChange={setCreateOpen}><DialogContent><DialogHeader><DialogTitle>Adicionar ponto de controlo</DialogTitle><DialogDescription>Crie um ponto, indicando a fábrica, área, periodicidade e tipo de material.</DialogDescription></DialogHeader>{pointForm(saveNew, "Criar ponto de controlo")}</DialogContent></Dialog><Dialog open={editOpen} onOpenChange={setEditOpen}><DialogContent className="max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>Editar ponto de controlo</DialogTitle><DialogDescription>Atualize os dados operacionais e associe uma imagem de referência opcional.</DialogDescription></DialogHeader>{pointForm(saveEdit, "Guardar alterações", true)}</DialogContent></Dialog></>;
}

function FragileInspectionDashboard({ createEntry, factoryId }: { createEntry: any; factoryId: string }) {
  const [periodicity, setPeriodicity] = useState("all");
  const [preselectedItemId, setPreselectedItemId] = useState<number | null>(null);
  const pendingInput = useMemo(() => factoryId ? { factoryId: Number(factoryId) } : undefined, [factoryId]);
  const pending = trpc.quality.fragilePending.useQuery(pendingInput, { enabled: Boolean(factoryId) });
  const periodLabel = { D: "Diário", S: "Semanal", Q: "Quinzenal", M: "Mensal" } as const;
  const points = (pending.data ?? []).filter((point) => periodicity === "all" || point.periodicity === periodicity);
  const counts = (pending.data ?? []).reduce<Record<"D" | "S" | "Q" | "M", number>>((result, point) => { result[point.periodicity] += 1; return result; }, { D: 0, S: 0, Q: 0, M: 0 });
  const openInspection = (itemId: number) => { setPreselectedItemId(itemId); requestAnimationFrame(() => document.getElementById("registo-quebraveis")?.scrollIntoView({ behavior: "smooth", block: "start" })); };

  const unifiedIntro = <div className="rounded-2xl border border-teal-100 bg-teal-50/70 p-5"><div className="flex flex-col gap-4 md:flex-row md:items-end md:justify-between"><div><p className="font-mono-ui text-xs uppercase tracking-[0.16em] text-teal-700">Gestão operacional</p><h2 className="mt-1 text-lg font-semibold text-teal-950">Pendências e catálogo de pontos</h2><p className="mt-1 text-sm text-teal-800">Filtre a periodicidade, priorize inspeções em falta e consulte ou edite os pontos da fábrica selecionada no mesmo fluxo.</p></div><Select value={periodicity} onValueChange={setPeriodicity}><SelectTrigger className="w-full bg-white md:w-52"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todas as periodicidades</SelectItem>{Object.entries(periodLabel).map(([code, label]) => <SelectItem key={code} value={code}>{code} — {label}</SelectItem>)}</SelectContent></Select></div>{factoryId && <div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4">{Object.entries(periodLabel).map(([code, label]) => <div key={code} className="rounded-xl border border-teal-100 bg-white p-3"><p className="font-mono-ui text-xs text-muted-foreground">{code} · {label}</p><p className="mt-1 text-2xl font-semibold text-slate-900">{counts[code as "D" | "S" | "Q" | "M"]}</p><p className="text-xs text-muted-foreground">pendentes</p></div>)}</div>}</div>;

  return <div className="space-y-6"><ModuleHeader label="Quebráveis" description="Centralize as pendências, o catálogo e o registo de inspeções num único fluxo operacional." icon={Boxes} />{unifiedIntro}<Card className="border-0 panel-shadow"><CardHeader><CardTitle className="flex items-center gap-2"><CalendarClock className="h-5 w-5 text-teal-700" />Inspeções pendentes</CardTitle><CardDescription>Registe diretamente os pontos em falta; o catálogo completo e a edição encontram-se na continuação desta mesma área.</CardDescription></CardHeader><CardContent>{!factoryId ? <div className="rounded-xl border border-dashed bg-slate-50 p-5 text-sm text-muted-foreground">Selecione uma fábrica ou linha no topo para calcular as inspeções pendentes.</div> : pending.isLoading ? <p className="py-5 text-sm text-muted-foreground">A calcular pendências…</p> : points.length ? <div className="divide-y rounded-xl border border-slate-100">{points.map((point) => <div key={point.id} className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="font-medium">{point.name}</p><Badge className="bg-slate-900 text-white hover:bg-slate-900">{point.periodicity} — {periodLabel[point.periodicity]}</Badge></div><p className="mt-1 text-sm text-muted-foreground">{point.location} · {point.lastInspectionAt ? `Última inspeção: ${new Date(point.lastInspectionAt).toLocaleDateString("pt-PT")}` : "Sem inspeções registadas"}</p></div><Button onClick={() => openInspection(point.id)}><ClipboardCheck className="mr-2 h-4 w-4" />Registar inspeção</Button></div>)}</div> : <div className="rounded-xl border border-emerald-100 bg-emerald-50 p-5 text-sm text-emerald-900"><CheckCircle2 className="mr-2 inline h-4 w-4" />Não existem pontos pendentes para os filtros selecionados.</div>}</CardContent></Card><div id="registo-quebraveis"><FragileInspectionV2 key={preselectedItemId ?? "sem-selecao"} createEntry={createEntry} factoryId={factoryId} preselectedItemId={preselectedItemId} showHeader={false} /></div></div>;
}
